package io.github.jesterportfolio.hearth.gathering;
import org.junit.jupiter.api.Test;
import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.atomic.AtomicLong;
import java.util.function.BooleanSupplier;
import static io.github.jesterportfolio.hearth.gathering.GatheringStore.*;
import static org.junit.jupiter.api.Assertions.*;

class GatheringDungeonTest {
    static GatheringContent content(){var box=new GatheringContent.Box(0,63,0,2,3,2);var blocks=new HashMap<GatheringContent.Cell,String>();box.cells().forEach(c->blocks.put(c,c.y()==63?"STONE":"AIR"));var template=new GatheringContent.Template("ore_one",blocks);return new GatheringContent("public_gathering",box,new GatheringContent.Position(5,64,5,0,0),new GatheringContent.Position(.5,64,.5,0,0),1000,100,template.version(),Map.of(template.version(),template));}
    static final class Repo implements GatheringStore {State row;int writes;boolean fail;Repo(){var c=content();var t=c.templates().get(c.active());row=new State(UUID.randomUUID(),c.id(),UUID.randomUUID(),0,0,c.area().hash(),t.version(),t.hash(),Phase.OPEN,null,true,1000);}
        public CompletionStage<State> read(){return CompletableFuture.completedFuture(row);}public CompletionStage<State> create(State s){row=s;return read();}public CompletionStage<State> save(State old,State next){if(fail||!row.equals(old))return CompletableFuture.failedFuture(new IllegalStateException("DB_FAILURE"));row=next;writes++;return read();}}
    static final class Person implements GatheringDungeon.Member {UUID id=UUID.randomUUID();Object token=new Object();boolean valid=true;public UUID player(){return id;}public Object session(){return token;}public boolean current(){return valid;}}
    static final class Port implements GatheringDungeon.Boundary {boolean valid=true,entered=true;String fail="";int prepares,saves,evacuations,applies,flushes,acks,enters,releases,notices;CompletableFuture<Void> saving=CompletableFuture.completedFuture(null),preparing=CompletableFuture.completedFuture(null);CompletableFuture<Boolean> entering;
        public boolean current(){return valid;}public void notice(String s){notices++;}CompletionStage<Void> step(String name){return fail.equals(name)?CompletableFuture.failedFuture(new IllegalStateException(name)):CompletableFuture.completedFuture(null);}
        public CompletionStage<Void> prepare(GatheringContent.Template t,UUID id,BooleanSupplier g){prepares++;return preparing.thenCompose(v->step("prepare"));}public CompletionStage<Void> save(List<GatheringDungeon.Member> m){saves++;return saving.thenCompose(v->step("save"));}public CompletionStage<Void> evacuate(List<GatheringDungeon.Member> m,BooleanSupplier g){evacuations++;return step("evacuate");}public CompletionStage<Void> apply(GatheringContent.Template t,BooleanSupplier g){applies++;return step("apply");}public CompletionStage<Void> flush(){flushes++;return step("flush");}public CompletionStage<Void> acknowledge(UUID r){acks++;return step("ack");}public CompletionStage<Boolean> enter(GatheringDungeon.Member m,long g,BooleanSupplier valid){enters++;return entering==null?CompletableFuture.completedFuture(entered&&valid.getAsBoolean()):entering;}public void release(){releases++;}}
    static GatheringDungeon dungeon(Repo repo,Port port,AtomicLong clock){return new GatheringDungeon(content(),repo,repo.row,port,Runnable::run,()->{},clock::get);}static void done(CompletionStage<?> f){f.toCompletableFuture().join();}static void failed(CompletionStage<?> f){assertThrows(CompletionException.class,()->done(f));}
    @Test void firstEntrySharedMembersPartialExitAndNextEntryReset(){var r=new Repo();var p=new Port();var d=dungeon(r,p,new AtomicLong());var a=new Person();var b=new Person();done(d.enter(a));done(d.enter(b));assertEquals(1,d.snapshot().generation());assertEquals(2,d.occupants());done(d.leave(a));assertFalse(d.snapshot().emptyReset());done(d.enter(a));assertEquals(1,p.applies);done(d.leave(a));done(d.leave(b));assertTrue(d.snapshot().emptyReset());done(d.enter(a));assertEquals(2,d.snapshot().generation());assertTrue(d.canGather(a,2));assertFalse(d.canGather(a,1));}
    @Test void periodicResetEvictsAndReentryDoesNotRepeatFreshReset(){var r=new Repo();var p=new Port();var clock=new AtomicLong();var d=dungeon(r,p,clock);var a=new Person();done(d.enter(a));clock.set(950);done(d.pulse());assertEquals(1,d.snapshot().generation());clock.set(1000);done(d.pulse());assertEquals(0,d.occupants());assertEquals(2,d.snapshot().generation());assertFalse(d.snapshot().emptyReset());done(d.enter(a));assertEquals(2,p.applies);assertTrue(p.notices>=3);}
    @Test void simultaneousResetRequestsShareWorkNoGenerationUntilSaveComplete(){var r=new Repo();var p=new Port();var d=dungeon(r,p,new AtomicLong());p.saving=new CompletableFuture<>();UUID id=UUID.randomUUID();var first=d.reset(id);assertSame(first,d.reset(UUID.randomUUID()));assertEquals(0,d.snapshot().generation());assertEquals(Phase.RESETTING,d.snapshot().phase());assertEquals(0,p.applies);var barrier=d.barrier();assertFalse(barrier.toCompletableFuture().isDone());p.saving.complete(null);done(first);done(barrier);done(d.reset(id));assertEquals(1,d.snapshot().generation());assertEquals(1,p.applies);}
    @Test void eachBoundaryFailureHoldsOldGenerationAndNeverContinues(){for(String name:List.of("prepare","save","evacuate","apply","flush","ack")){var r=new Repo();var p=new Port();p.fail=name;var d=dungeon(r,p,new AtomicLong());failed(d.reset(UUID.randomUUID()));assertEquals(Phase.ERROR_HOLD,d.snapshot().phase(),name);assertEquals(0,d.snapshot().generation(),name);assertEquals(0,r.row.generation(),name);assertEquals(1,p.releases);if(List.of("prepare","save","evacuate").contains(name))assertEquals(0,p.applies);failed(d.enter(new Person()));}}
    @Test void dbFailureCannotApplyOrBecomeSuccess(){var r=new Repo();r.fail=true;var p=new Port();var d=dungeon(r,p,new AtomicLong());var original=r.row;failed(d.reset(UUID.randomUUID()));assertEquals(original,r.row);assertEquals(0,p.applies);assertEquals(Phase.ERROR_HOLD,d.snapshot().phase());}
    @Test void staleWorldDuringSavePreventsApply(){var r=new Repo();var p=new Port();p.saving=new CompletableFuture<>();var d=dungeon(r,p,new AtomicLong());var f=d.reset(UUID.randomUUID());p.valid=false;p.saving.complete(null);failed(f);assertEquals(0,p.applies);assertEquals(0,d.snapshot().generation());}
    @Test void sameSessionDuplicateEntrySharesPendingAndQuitBlocksLateMove(){var r=new Repo();var p=new Port();p.entering=new CompletableFuture<>();var d=dungeon(r,p,new AtomicLong());var a=new Person();var first=d.enter(a);assertSame(first,d.enter(a));assertFalse(d.settled());done(d.leave(a));a.valid=false;p.entering.complete(true);failed(first);done(d.barrier());assertEquals(0,d.occupants());assertFalse(d.canGather(a,1));}
    @Test void changedSessionDoesNotInheritReservation(){var r=new Repo();var p=new Port();p.entering=new CompletableFuture<>();var d=dungeon(r,p,new AtomicLong());var a=new Person();var first=d.enter(a);var b=new Person();b.id=a.id;failed(d.enter(b));assertFalse(d.reserved(b));assertTrue(d.reserved(a));p.entering.complete(true);done(first);failed(d.enter(b));}
    @Test void enterWaitsForPendingResetAndFailureCannotAdmit(){var r=new Repo();var p=new Port();p.saving=new CompletableFuture<>();var d=dungeon(r,p,new AtomicLong());var reset=d.reset(UUID.randomUUID());var entry=d.enter(new Person());assertEquals(0,p.enters);p.saving.completeExceptionally(new IllegalStateException("DB_DOWN"));failed(reset);failed(entry);assertEquals(0,p.enters);}
    @Test void closeDuringPreparationDoesNotMutateOldWorld(){var r=new Repo();var p=new Port();p.preparing=new CompletableFuture<>();var d=dungeon(r,p,new AtomicLong());var f=d.enter(new Person());d.close();p.preparing.complete(null);failed(f);assertEquals(0,p.applies);assertEquals(0,p.enters);assertTrue(d.settled());}
    @Test void separateRunsRemainIndependentWhileOneIsHeld(){var r=new Repo();var p=new Port();p.fail="save";var a=dungeon(r,p,new AtomicLong());var other=new Repo();var bp=new Port();var b=dungeon(other,bp,new AtomicLong());failed(a.reset(UUID.randomUUID()));done(b.enter(new Person()));assertEquals(1,b.snapshot().generation());assertNotEquals(a.snapshot().run(),b.snapshot().run());}
    @Test void restoredPendingOrErrorNeverBecomesOpenAutomatically(){for(var phase:List.of(Phase.RESETTING,Phase.ERROR_HOLD)){var r=new Repo();var x=r.row;r.row=new State(x.run(),x.dungeon(),x.world(),x.revision(),x.generation(),x.area(),x.template(),x.hash(),phase,UUID.randomUUID(),true,1000);var p=new Port();var d=dungeon(r,p,new AtomicLong());failed(d.enter(new Person()));assertEquals(0,p.prepares);}}
    @Test void unrecognizedTemplateOrBoundsAreRejectedWithoutWrite(){var r=new Repo();var x=r.row;r.row=new State(x.run(),x.dungeon(),x.world(),0,1,x.area(),"unknown",x.hash(),Phase.OPEN,null,false,1000);assertThrows(IllegalArgumentException.class,()->dungeon(r,new Port(),new AtomicLong()));assertEquals(0,r.writes);}
    @Test void failedEntryIsNotAnOccupant(){var r=new Repo();var p=new Port();p.entered=false;var d=dungeon(r,p,new AtomicLong());failed(d.enter(new Person()));assertEquals(0,d.occupants());assertTrue(d.settled());}
    @Test void lastExitBookkeepingIncludedInBarrier(){var r=new Repo();var p=new Port();var d=dungeon(r,p,new AtomicLong());var a=new Person();done(d.enter(a));done(d.leave(a));done(d.barrier());assertTrue(r.row.emptyReset());assertTrue(d.settled());}
    @Test void resetWaitsForAlreadyStartedEntryAndRejectsItsLateAdmission(){var r=new Repo();var p=new Port();var d=dungeon(r,p,new AtomicLong());p.entering=new CompletableFuture<>();var a=new Person();var entry=d.enter(a);assertEquals(1,d.snapshot().generation());var reset=d.reset(UUID.randomUUID());assertFalse(d.reserved(a));assertEquals(1,p.applies);assertFalse(reset.toCompletableFuture().isDone());p.entering.complete(true);failed(entry);done(reset);assertEquals(2,d.snapshot().generation());assertEquals(0,d.occupants());assertFalse(d.canGather(a,1));assertEquals(2,p.evacuations);}

}
